import React, { useState, useEffect, useContext } from 'react';
import { Link, Navigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { toast } from 'react-toastify';
import api from '../services/api';
import { AuthContext } from '../context/AuthContext';
import MD5 from 'crypto-js/md5';
import { v4 as uuidv4 } from 'uuid';
import Console, { Card } from '../workspaces/Console';
import '../workspaces/workspaces.css';

const Profile = () => {
  const { user, token, logout, isLoading } = useContext(AuthContext);
  const [userData, setUserData] = useState({});
  const [savedSnapshot, setSavedSnapshot] = useState({});
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [apiToken, setApiToken] = useState('');

  const getGravatarUrl = (email, size = 80) => {
    if (!email) {
      const seed = userData.username || 'unknown';
      return `https://robohash.org/${seed}?set=set2&size=${size}x${size}`;
    }

    const hash = MD5(email.trim().toLowerCase()).toString();
    return `https://www.gravatar.com/avatar/${hash}?d=retro&s=${size}`;
  };

useEffect(() => {
  const fetchData = async () => {
    setLoading(true);

    try {
      // Her istek için kesinlikle unique UUID
      const cachebuster = uuidv4();

      const profileResponse = await api.get(`/profile?cb=${cachebuster}`, {
        headers: { Authorization: token },
      });
      setUserData(profileResponse.data);
      setSavedSnapshot(profileResponse.data);
    } catch (err) {
      if (err.response?.status === 401) logout();
    } finally {
      setLoading(false);
    }
  };

  if (token) fetchData();
}, [token]);



  const handleUpdate = async () => {
    setIsSaving(true);
    try {
      await api.put('/profile', userData, {
        headers: { Authorization: token },
      });
      toast.success('Profile updated successfully');
      setIsEditing(false);
    } catch (err) {
      toast.error('Update failed');
    } finally {
      setIsSaving(false);
    }
  };

  const handleCancelEdit = () => {
    // Zeigarnik: warn before discarding typed changes instead of silently dropping them.
    if (isDirty && !window.confirm('Discard your changes?')) return;
    setUserData({ ...userData, ...savedSnapshot });
    setIsEditing(false);
  };

  const handleGenerateToken = async () => {
    // Say what actually breaks (Tesler): the old token stops working, so scripts using it fail.
    let r = confirm('Generate a new token? Existing scripts and apps using your current token will stop working.')
    if (!r){
        return;
    }
    try {
      const response = await api.post('/generate-api-token', {}, {
        headers: { Authorization: token },
      });
      setApiToken(response.data.api_token);
      toast.success('API token generated successfully');
    } catch (err) {
      toast.error('Token generation failed');
    }
  };

  const copyToClipboard = async (text) => {
    // Postel: only claim success after the clipboard actually accepts the text.
    try {
      await navigator.clipboard.writeText(text);
      toast.success('Copied to clipboard!');
    } catch {
      toast.error('Copy failed — please copy the text manually.');
    }
  };

  const isDirty = ['full_name', 'company'].some(
    (key) => (userData[key] || '') !== (savedSnapshot[key] || '')
  );

  const crumbs = [{ label: 'Profile' }];
  if (isLoading) {
    return (
      <Console crumbs={crumbs}>
        <main className="cs-main">
          <h1 className="sr-only">Profile</h1>
          <p className="ws-status" role="status">Loading your account...</p>
        </main>
      </Console>
    );
  }
  if (!token) return <Navigate to="/login" replace />;
  if (loading) {
    return (
      <Console crumbs={crumbs}>
        <main className="cs-main">
          <h1 className="sr-only">Profile</h1>
          <p className="ws-status" role="status">Loading your profile...</p>
        </main>
      </Console>
    );
  }

  const displayName = userData.full_name || userData.username;
  const avatar = (size, className) => (
    <img
      src={getGravatarUrl(userData.email, size * 2)}
      alt=""
      width={size}
      height={size}
      className={className}
      onError={(e) => {
        if (e.target.src.includes('robohash.org')) return; // the fallback failed too: stop, do not loop
        const seed = userData.username || 'unknown';
        e.target.src = `https://robohash.org/${seed}?set=set2&size=${size * 2}x${size * 2}`;
      }}
    />
  );
  const field = (id, label, key, editable = false) => (
    <li className="cs-row cs-row--wrap">
      <label className="cs-row__label" htmlFor={id}>{label}</label>
      <input
        id={id}
        className="cs-field"
        type={key === 'email' ? 'email' : 'text'}
        value={userData[key] || ''}
        onChange={editable ? (e) => setUserData({ ...userData, [key]: e.target.value }) : undefined}
        disabled={!editable || !isEditing}
        readOnly={!editable}
      />
    </li>
  );

  return (
    <Console crumbs={crumbs}>
      <main className="cs-main cs-main--page">
        <Helmet>
          <title>Profile · Plotune</title>
          <meta name="robots" content="noindex,nofollow" />
        </Helmet>
        <h1 className="sr-only">Profile</h1>

        <Card
          title="Details"
          headingId="profile-info"
          action={!isEditing ? (
            <button type="button" className="cs-action" onClick={() => setIsEditing(true)}>Edit</button>
          ) : (
            <span className="cs-row__side">
              <button type="button" className="cs-action" onClick={handleCancelEdit}>Cancel</button>
              <button type="button" className="cs-button" onClick={handleUpdate} disabled={isSaving}>{isSaving ? 'Saving…' : 'Save changes'}</button>
            </span>
          )}
        >
          <ul className="cs-list" aria-labelledby="profile-info">
            <li className="cs-row">
              {avatar(40, 'cs-avatar-img')}
              <span className="cs-row__main">
                <strong translate="no">{displayName}</strong>
                <span translate="no">{userData.email}</span>
              </span>
              <span className="cs-row__side">
                <a className="cs-action" href="https://gravatar.com" target="_blank" rel="noopener noreferrer" title="Your profile picture is managed through Gravatar.">
                  Change on Gravatar<span className="sr-only"> (opens in a new tab)</span>
                </a>
              </span>
            </li>
            {field('profile-username', 'Username', 'username')}
            {field('profile-email', 'Email address', 'email')}
            {field('profile-name', 'Full name', 'full_name', true)}
            {field('profile-company', 'Company', 'company', true)}
            {field('profile-sector', 'Sector', 'sector')}
          </ul>
        </Card>

        <Card title="API access" headingId="profile-api">
          <ul className="cs-list" aria-labelledby="profile-api">
            <li className="cs-row">
              <span className="cs-row__main">
                <strong>API documentation</strong>
                <span>How to use the Plotune API.</span>
              </span>
              <span className="cs-row__side"><Link to="/docs" className="cs-action">Open</Link></span>
            </li>
            <li className="cs-row cs-row--wrap">
              <span className="cs-row__main" title="Generate an API token to integrate Plotune with your applications and scripts. Keep this token secure and never share it publicly.">
                <strong>API token</strong>
                <span>For your scripts and apps. Keep it secret.</span>
              </span>
              <span className="cs-row__side">
                <button type="button" className="cs-action cs-action--danger" onClick={handleGenerateToken} title="The token you use now stops working.">Generate new token</button>
              </span>
              {apiToken && (
                <>
                  <p className="cs-token" aria-label="Your API token">{apiToken}</p>
                  <span className="cs-row__main"><span role="alert">Copy this token now! It won't be shown again.</span></span>
                  <span className="cs-row__side"><button type="button" className="cs-action" onClick={() => copyToClipboard(apiToken)}>Copy</button></span>
                </>
              )}
            </li>
          </ul>
        </Card>

        <Card title="Security" headingId="profile-security">
          <ul className="cs-list" aria-labelledby="profile-security">
            <li className="cs-row">
              <span className="cs-row__main">
                <strong>Password</strong>
                <span>Change your password to keep your account secure.</span>
              </span>
              <span className="cs-row__side"><Link to="/reset-password" className="cs-action">Change password</Link></span>
            </li>
          </ul>
        </Card>
      </main>
    </Console>
  );
};

export default Profile;
